sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // ===== CONFIG =====
    var CLOSED_COMPLETE_VALUE = '3';
    var ISSUE_KEY_FIELD = 'u_jira_issue_key';
    var REST_MESSAGE_NAME = 'Jira - Validate Issue';
    var REST_METHOD_NAME = 'GET Validate Issue';
    // ==================

    // Run only when moving to Closed Complete
    if (!current.state.changes() || current.state.toString() != CLOSED_COMPLETE_VALUE) {
        return;
    }

    // ------------------------------------------------------------------
    // Validate Jira Issue Key
    // ------------------------------------------------------------------
    var issueKey = current.getValue(ISSUE_KEY_FIELD);

    if (!issueKey) {
        gs.addErrorMessage('Please enter a valid Jira Issue Key before closing this Catalog Task.');
        current.state = previous.state;
        current.setAbortAction(true);
        return;
    }

    issueKey = issueKey.toString().trim().toUpperCase();

    // Current Catalog Task Number
    var taskNumber = current.number.toString();

    // ------------------------------------------------------------------
    // Validate Jira Issue using REST API
    // ------------------------------------------------------------------
    var response;

    try {

        var rm = new sn_ws.RESTMessageV2(
            REST_MESSAGE_NAME,
            REST_METHOD_NAME
        );

        rm.setStringParameterNoEscape('issue_key', issueKey);

        response = rm.execute();

    } catch (ex) {

        gs.addErrorMessage('Unable to connect to Jira.');

        current.state = previous.state;
        current.setAbortAction(true);

        return;
    }

    // ------------------------------------------------------------------
    // HTTP Response Validation
    // ------------------------------------------------------------------
    if (response.getStatusCode() != 200) {

        gs.addErrorMessage('Invalid Jira Issue Key. Jira returned HTTP ' + response.getStatusCode() + '.');

        current.state = previous.state;
        current.setAbortAction(true);

        return;
    }

    // ------------------------------------------------------------------
    // Parse Response
    // ------------------------------------------------------------------
    var body;

    try {

        body = JSON.parse(response.getBody());

    } catch (ex) {

        gs.addErrorMessage('Unable to parse Jira response.');

        current.state = previous.state;
        current.setAbortAction(true);

        return;
    }

    // ------------------------------------------------------------------
    // Validate Catalog Task Number in Jira Description
    // ------------------------------------------------------------------
    var description = '';

    if (body.fields && body.fields.description) {
        description = JSON.stringify(body.fields.description);
    }

    if (description.indexOf(taskNumber) == -1) {

        gs.addErrorMessage(
            'The Jira story description must contain the current Catalog Task Number (' +
            taskNumber +
            '). Please update the Jira ticket before closing this task.'
        );

        current.state = previous.state;
        current.setAbortAction(true);

        return;
    }

    // ------------------------------------------------------------------
    // Success
    // ------------------------------------------------------------------
    current.short_description = 'Created jira ticket manually';

  // ------------------------------------------------------------------
// Check if any other Catalog Tasks are still open
// ------------------------------------------------------------------
var ritmSysId = current.request_item.toString();

var grTask = new GlideRecord('sc_task');
grTask.addQuery('request_item', ritmSysId);
grTask.addQuery('sys_id', '!=', current.sys_id); // Ignore current task
grTask.addQuery('state', '!=', CLOSED_COMPLETE_VALUE);
grTask.query();

if (grTask.hasNext()) {

    gs.addInfoMessage(
        'This Catalog Task has been closed successfully. However, the parent RITM cannot be closed because there are other Catalog Tasks that are still open.'
    );

} else {

    var ritm = new GlideRecord('sc_req_item');

    if (ritm.get(ritmSysId)) {
        ritm.state = CLOSED_COMPLETE_VALUE;
        ritm.stage = 'complete';
		ritm.u_jira_issue_key=issueKey;
		ritm.assignment_group="Story Managment Group";
        ritm.update();
    }
}
})(current, previous);
